import 'phonetic_algorithms.dart';

/// Autocomplete suggestion generated by the Trie.
class AutocompleteSuggestion {
  final String text;
  final String category;
  final String? entityId;
  final int frequency;
  final String? subtitle;

  const AutocompleteSuggestion({
    required this.text,
    required this.category,
    this.entityId,
    this.frequency = 1,
    this.subtitle,
  });

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AutocompleteSuggestion &&
          runtimeType == other.runtimeType &&
          text.toLowerCase() == other.text.toLowerCase() &&
          category == other.category;

  @override
  int get hashCode => text.toLowerCase().hashCode ^ category.hashCode;
}

/// Node in the Prefix Trie.
class TrieNode {
  final Map<String, TrieNode> children = {};
  bool isEndOfWord = false;
  final List<AutocompleteSuggestion> suggestions = [];
  int hitCount = 0;
}

/// Frequency-Ranked Prefix Trie for $O(k)$ Typeahead and Autocompletion.
/// Powers instant predictive search suggestions used by leading search engines.
class SearchPrefixTrie {
  final TrieNode root = TrieNode();

  /// Inserts a phrase or word into the Trie with its category and entity metadata.
  void insert({
    required String text,
    required String category,
    String? entityId,
    int frequency = 1,
    String? subtitle,
  }) {
    final clean = SearchPhonetics.normalizeAccents(text.toLowerCase().trim());
    if (clean.isEmpty) return;

    final suggestion = AutocompleteSuggestion(
      text: text.trim(),
      category: category,
      entityId: entityId,
      frequency: frequency,
      subtitle: subtitle,
    );

    // Insert whole phrase
    _insertTerm(clean, suggestion);

    // Also insert individual word prefixes for multi-word titles (e.g. "Sharma" inside "Rohit Sharma")
    final words = clean.split(RegExp(r'\s+')).where((w) => w.length >= 3).toList();
    if (words.length > 1) {
      for (final w in words) {
        _insertTerm(w, suggestion);
      }
    }
  }

  void _insertTerm(String term, AutocompleteSuggestion suggestion) {
    TrieNode current = root;

    for (int i = 0; i < term.length; i++) {
      final char = term[i];
      current = current.children.putIfAbsent(char, () => TrieNode());

      // Maintain top suggestions sorted by frequency at each prefix level
      final existingIndex = current.suggestions.indexWhere(
        (s) => s.text.toLowerCase() == suggestion.text.toLowerCase(),
      );
      if (existingIndex >= 0) {
        if (suggestion.frequency > current.suggestions[existingIndex].frequency) {
          current.suggestions[existingIndex] = suggestion;
        }
      } else {
        current.suggestions.add(suggestion);
        current.suggestions.sort((a, b) => b.frequency.compareTo(a.frequency));
        if (current.suggestions.length > 8) {
          current.suggestions.removeLast();
        }
      }
    }

    current.isEndOfWord = true;
    current.hitCount += suggestion.frequency;
  }

  /// Retrieves top autocompletion suggestions matching the prefix [prefix] in $O(k)$ time.
  List<AutocompleteSuggestion> predict(String prefix, {int limit = 5}) {
    final cleanPrefix = SearchPhonetics.normalizeAccents(prefix.toLowerCase().trim());
    if (cleanPrefix.isEmpty) return const [];

    TrieNode current = root;
    for (int i = 0; i < cleanPrefix.length; i++) {
      final char = cleanPrefix[i];
      if (!current.children.containsKey(char)) {
        return const [];
      }
      current = current.children[char]!;
    }

    // Return the cached top suggestions at this prefix node
    final results = List<AutocompleteSuggestion>.from(current.suggestions);
    results.sort((a, b) => b.frequency.compareTo(a.frequency));
    return results.take(limit).toList();
  }

  /// Clear the trie.
  void clear() {
    root.children.clear();
    root.suggestions.clear();
  }
}

